<span class="line"><span style="color:#C678DD;">        raise</span><span style="color:#61AFEF;"> HTTPException</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">400</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;无法找到相关数据表，请检查问题描述&quot;</span><span style="color:#ABB2BF;">)</span></span>
