<span class="line"><span style="color:#ABB2BF;">        data </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> await</span><span style="color:#ABB2BF;"> executor.</span><span style="color:#61AFEF;">execute</span><span style="color:#ABB2BF;">(sql_result.sql)</span></span>
