<span class="line"><span style="color:#ABB2BF;">    chart_config, insight </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> await</span><span style="color:#ABB2BF;"> asyncio.</span><span style="color:#61AFEF;">gather</span><span style="color:#ABB2BF;">(</span></span>
